1454	/// A publish document that passed every check that can run before
1455	/// taking the package lock: the caller may publish the package, and
1456	/// each attachment maps to a canonical disk filename and a
1457	/// `versions[v].dist` block.
1458	struct ValidatedPublish {
1459	    name: PackageName,
1460	    /// The publish body with `_attachments` stripped.
1461	    incoming: Value,
1462	    /// One `(attachment, canonical disk filename, dist)` triple per
1463	    /// attachment.
1464	    prepared: Vec<(PendingAttachment, String, Value)>,
1465	}
1466	
1467	async fn validate_publish_doc(
1468	    state: &AppState,
1469	    identity: &Identity,
1470	    name: PackageName,
1471	    mut incoming: Value,
1472	) -> Result<ValidatedPublish, RegistryError> {
1473	    authorize(state, identity, name.as_str(), Action::Publish)?;
1474	
1475	    let attachments = extract_attachments(&mut incoming)?;
1476	
1477	    // Resolve each attachment's canonical disk filename + matching
1478	    // `versions[v].dist` block. Attachment names that don't match the
1479	    // package (`bar-1.0.0.tgz` for `foo`) or that try to escape the
1480	    // package dir (`../../etc/passwd.tgz`) are rejected here, before
1481	    // any I/O. The canonical name is what we actually persist — for
1482	    // scoped libnpmpublish bodies the wire form is `@scope/name-version.tgz`
1483	    // but on disk it lives at `<root>/@scope/name/name-version.tgz`,
1484	    // matching what `serve_tarball` expects.
1485	    let mut prepared: Vec<(PendingAttachment, String, Value)> =
1486	        Vec::with_capacity(attachments.len());
1487	    for attachment in attachments {
1488	        let (canonical, version) = name.parse_tarball_name(&attachment.filename)?;
1489	        let dist = incoming
1490	            .get("versions")
1491	            .and_then(|versions| versions.get(&version))
1492	            .and_then(|manifest| manifest.get("dist"))
1493	            .cloned()
1494	            .unwrap_or(Value::Null);
1495	        prepared.push((attachment, canonical, dist));
1496	    }
1497	    Ok(ValidatedPublish { name, incoming, prepared })
1498	}
