204	/// Merge an incoming publish manifest into the existing on-disk
205	/// packument. The result is what we'll write back to
206	/// `<storage>/<pkg>/package.json`.
207	///
208	/// Merge rules (chosen to match verdaccio's behavior for the cases
209	/// `@pnpm/registry-mock`'s publish script exercises):
210	///
211	/// * `name`, `_id` — copied from the new body.
212	/// * `versions` — union, with the new body's entries taking
213	///   precedence when keys collide.
214	/// * `dist-tags` — union, new body overrides on key collision.
215	/// * `time` — union, new entries override on key collision.
216	///   `time.modified` is always bumped to "now".
217	/// * Other top-level keys (`description`, `readme`, `maintainers`,
218	///   `users`, etc.) come from the new body when present, falling
219	///   back to the existing packument otherwise.
220	pub fn merge_manifest(existing: Option<&Value>, incoming: &Value, now_iso: &str) -> Value {
221	    let mut out = match existing {
222	        Some(Value::Object(obj)) => obj.clone(),
223	        _ => Map::new(),
224	    };
225	
226	    if let Some(incoming_obj) = incoming.as_object() {
227	        for (key, value) in incoming_obj {
228	            match key.as_str() {
229	                "versions" => {
230	                    let merged = merge_objects(out.get(key), value);
231	                    out.insert(key.clone(), merged);
232	                }
233	                "dist-tags" => {
234	                    let merged = merge_objects(out.get(key), value);
235	                    out.insert(key.clone(), merged);
236	                }
237	                "time" => {
238	                    let merged = merge_objects(out.get(key), value);
239	                    out.insert(key.clone(), merged);
240	                }
241	                "_attachments" => {
242	                    // Already stripped by extract_attachments; if it
243	                    // slips through somehow, drop it so we don't
244	                    // persist base64 blobs alongside the packument.
245	                }
246	                _ => {
247	                    out.insert(key.clone(), value.clone());
248	                }
249	            }
250	        }
251	    }
252	
253	    // Synthesize time entries for any new version that didn't get
254	    // one supplied by the client. pnpm reads `time.modified` for
255	    // freshness checks, so it must always be present.
256	    let version_ids: Vec<String> = out
257	        .get("versions")
258	        .and_then(Value::as_object)
259	        .map(|versions| versions.keys().cloned().collect())
260	        .unwrap_or_default();
261	    let time_entry = out.entry("time".to_string()).or_insert_with(|| Value::Object(Map::new()));
262	    if let Some(time_obj) = time_entry.as_object_mut() {
263	        time_obj.insert("modified".to_string(), Value::String(now_iso.to_string()));
264	        time_obj.entry("created".to_string()).or_insert_with(|| Value::String(now_iso.to_string()));
265	        for version_id in version_ids {
266	            time_obj.entry(version_id).or_insert_with(|| Value::String(now_iso.to_string()));
267	        }
268	    }
269	
270	    // Sort `versions` by semver-ish key order so the on-disk file is
271	    // stable across runs. Use a BTreeMap to take advantage of
272	    // serde_json's `preserve_order` feature — without sorting, two
273	    // publishes of the same package can produce different bytes.
274	    if let Some(versions) = out.get_mut("versions").and_then(Value::as_object_mut) {
275	        let sorted: BTreeMap<String, Value> =
276	            versions.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
277	        *versions = sorted.into_iter().collect();
278	    }
279	
280	    Value::Object(out)
281	}
