296	/// Format the current time as an ISO-8601 / RFC-3339 string with
297	/// millisecond precision (e.g. `2025-01-02T03:04:05.678Z`). Matches
298	/// the shape npm and verdaccio use in `time.modified`.
299	pub fn now_iso() -> String {
300	    use std::time::{SystemTime, UNIX_EPOCH};
301	    let since_epoch = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
302	    iso_from_unix_millis(since_epoch.as_millis() as i64)
