#[test]
fn falls_back_to_version_name_when_basename_missing() {
    // A `dist.tarball` ending in a trailing slash has no usable basename,
    // so the rewrite reconstructs the conventional `<name>-<version>.tgz`.
    let mut doc = json!({
        "versions": {
            "1.0.0": { "dist": { "tarball": "https://registry.npmjs.org/foo/" } }
        }
    });
    let name = PackageName::parse("foo").unwrap();
    rewrite_tarball_urls(&mut doc, &name, "http://127.0.0.1:4873");
    assert_eq!(
        doc["versions"]["1.0.0"]["dist"]["tarball"],
        "http://127.0.0.1:4873/foo/-/foo-1.0.0.tgz",
    );
}

